# Write the self-contained HTML report.

def img_tag(name):
    p = FIG_DIR / f"{name}.png"
    if not p.exists():
        return ""
    return f'&lt;figure&gt;&lt;img src="data:image/png;base64,{base64.b64encode(p.read_bytes()).decode()}"&gt;&lt;figcaption&gt;{name}&lt;/figcaption&gt;&lt;/figure&gt;'

def table(df, **kw):
    return df.to_html(classes="t", border=0, na_rep="", **kw) if isinstance(df, pd.DataFrame) and len(df) else "&lt;p&gt;none&lt;/p&gt;"

sections = [
    ("Release status", f"&lt;p class='status {RELEASE_STATUS}'&gt;{RELEASE_STATUS.upper()}&lt;/p&gt;"
                       + ("&lt;ul&gt;" + "".join(f"&lt;li&gt;{m}&lt;/li&gt;" for m in failure_modes) + "&lt;/ul&gt;" if failure_modes else "")),
    ("QA checklist", table(qa_table, index=False)),
    ("Scene catalog", table(catalog_out.drop(columns=["inc_min", "inc_max"]), index=False) + img_tag("tide_wind") + img_tag("quicklooks")),
    ("Per-scene classification", img_tag("threshold_master") + img_tag("classified_scenes")),
    ("Land frequency and classes (km²)", table(period_table, index=False) + img_tag("dry_season_areas") + img_tag("land_frequency") + img_tag("lowtide_composite")),
    ("Change", table(change_table, index=False) + table(summary_change)
               + "".join(img_tag(f"change_{t}") for t in CHANGE_MAPS)),
    ("Char maturity", "".join(img_tag(f"maturity_{y}") for y in MATURITY_MAPS)),
    ("Char register (interior chars, top 25 per period)",
     table(interior.sort_values("area_km2", ascending=False).groupby("period").head(25)
           [["period", "char_id", "status", "area_km2", "stable_share", "shift_m", "bearing_deg", "maturity_name", "age_years"]]
           .round(3), index=False) + img_tag("char_register")),
    ("Shoreline change", table(pd.DataFrame([{"pair": f"{a} → {b}", "transects": len(tr), "intersecting": int(tr.nsm_m.notna().sum()),
                                             "NSM median (m)": tr.nsm_m.median(), "EPR median (m/yr)": tr.epr_m_yr.median()}
                                            for (a, b), tr in TRANSECTS.items()]), index=False)
                         + "".join(img_tag(f"shoreline_{a}__{b}") for a, b in TRANSECTS)),
    ("NISAR parallel series", (table(nisar.drop(columns=["file"], errors="ignore"), index=False)
                               + (table(NISAR_RESULT["xtab"].round(1)) if NISAR_RESULT and "xtab" in NISAR_RESULT else "")
                               + img_tag("nisar")) if len(nisar) else "&lt;p&gt;no NISAR data&lt;/p&gt;"),
    ("Validation", table(accuracy_table, index=False)),
]
html = f'''&lt;!doctype html&gt;&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;title&gt;Charland report {years[-1]}&lt;/title&gt;
&lt;style&gt;body{{font-family:system-ui,sans-serif;max-width:1150px;margin:24px auto;padding:0 16px;color:#222}}
h1{{font-size:24px}} h2{{font-size:18px;border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:32px}}
table.t{{border-collapse:collapse;font-size:12px;margin:8px 0}} .t td,.t th{{padding:3px 8px;border-bottom:1px solid #eee;text-align:right}}
img{{max-width:100%}} figcaption{{font-size:11px;color:#777}} .status{{font-weight:700;font-size:18px}}
.provisional{{color:#b9770e}} .final{{color:#1e8449}}&lt;/style&gt;&lt;/head&gt;&lt;body&gt;
&lt;h1&gt;Charland monitoring report, lower Meghna estuary, {years[-1]}&lt;/h1&gt;
&lt;p&gt;Sentinel-1 IW GRDH, relative orbit {MAIN_ORBIT} {MAIN_PASS.lower()}, {len(selected)} scenes ({len(usable)} usable);
grid {GRID_CRS} at {RESOLUTION_M:g} m. Generated {datetime.now():%Y-%m-%d %H:%M}.&lt;/p&gt;
{"".join(f"&lt;h2&gt;{t}&lt;/h2&gt;{b}" for t, b in sections)}
&lt;/body&gt;&lt;/html&gt;'''
REPORT_PATH = OUT["reports"] / f"charland_report_{years[-1]}.html"
REPORT_PATH.write_text(html, encoding="utf-8")
print(f"Report written: {REPORT_PATH} ({REPORT_PATH.stat().st_size / 1e6:.1f} MB)")


